#define THICKNESS 0.2
#define RADIUS 0.2 // 끝부분 원의 반지름
#define AA (5.0 / iResolution.y)

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // UV 좌표 설정 (0.0 ~ 1.0)
    vec2 uv = fragCoord / iResolution.xy;
    uv -= vec2(0.0, 0.5); // UV를 (-0.5, -0.5) ~ (0.5, 0.5)로 이동
    uv.x *= iResolution.x / iResolution.y; // X축을 종횡비로 보정
    uv.y *= 1.0; // Y축은 그대로


    float progress = fract(iTime * 0.5)*2.0; // 속도 조절 (0.1은 속도 계수)

    // 프로그래스 바의 직선 부분 그리기
    float bar = smoothstep(THICKNESS + AA, THICKNESS - AA, abs(uv.y - 0.0)) * step(uv.x, progress);

    // 끝부분 둥근 원 그리기
    vec2 circlePos = vec2(progress, 0.0); // 진행도에 따라 원의 위치 설정
    // 원 위치의 X축을 종횡비에 맞게 보정하고 0~1 구간으로 설정
    circlePos.x = progress; // 왼쪽 끝에서 오른쪽 끝으로 진행


    // 원 그리기
    float circle = smoothstep(RADIUS + AA, RADIUS - AA, length(uv - circlePos));

    // 직선과 원을 결합
    float result = max(bar, circle);

    fragColor = vec4(result, result, result, 1.0);
}
